const upsertRateLimitHit = `-- name: UpsertRateLimitHit :one
INSERT INTO rate_limits (key, kategori, hit_count, window_reset_at, blocked_until, updated_at)
VALUES (
    $1,
    $2,
    1,
    NOW() + make_interval(secs => $3::int),
    NULL,
    NOW()
)
ON CONFLICT (key) DO UPDATE
SET hit_count = CASE
        WHEN rate_limits.window_reset_at <= NOW() THEN 1
        ELSE rate_limits.hit_count + 1
    END,
    window_reset_at = CASE
        WHEN rate_limits.window_reset_at <= NOW() THEN NOW() + make_interval(secs => $3::int)
        ELSE rate_limits.window_reset_at
    END,
    blocked_until = CASE
        WHEN rate_limits.window_reset_at <= NOW() AND (rate_limits.blocked_until IS NULL OR rate_limits.blocked_until <= NOW()) THEN NULL
        ELSE rate_limits.blocked_until
    END,
    updated_at = NOW()
RETURNING key, kategori, hit_count, window_reset_at, blocked_until, updated_at
`

type UpsertRateLimitHitParams struct {
	Key        string `json:"key"`
	Kategori   string `json:"kategori"`
	WindowSecs int32  `json:"window_secs"`
}

func (q *Queries) UpsertRateLimitHit(ctx context.Context, arg UpsertRateLimitHitParams) (RateLimit, error) {
	row := q.db.QueryRow(ctx, upsertRateLimitHit, arg.Key, arg.Kategori, arg.WindowSecs)
	var i RateLimit
	err := row.Scan(
		&i.Key,
		&i.Kategori,
		&i.HitCount,
		&i.WindowResetAt,
		&i.BlockedUntil,
		&i.UpdatedAt,
	)
	return i, err
}
